function clamp(value, low, high) {
  // return value limited to the range low..high
}

exercises.solution:
function clamp(value, low, high) {
  return value < low ? low : value > high ? high : value
}

exercises.starter:
function exactlyOne(a, b) {
  // return true when exactly one of a, b is true
}

exercises.solution:
function exactlyOne(a, b) {
  return (a || b) && !(a && b)
}
